// src/lib/attention.ts
function attentionSignals(sources) {
  const signals = [];
  const held = sources.intercept?.pending ?? 0;
  if (held > 0) {
    signals.push({
      tool: "proxy",
      count: held,
      label: `${held} held ${held === 1 ? "request" : "requests"} — interception is holding traffic; open Proxy, then Intercept, to release ${held === 1 ? "it" : "them"}`
    });
  }
  signals.push(...scannerSignals(sources.liveAudit));
  signals.push(...dashboardSignals(sources.crawls));
  return signals;
}
function scannerSignals(live) {
  const skipped = live?.skipped ?? 0;
  if (skipped <= 0) {
    return [];
  }
  return [{
    tool: "scanner",
    count: skipped,
    label: `${skipped} ${skipped === 1 ? "exchange" : "exchanges"} the live audit gave up on — open Scanner, then Live audit, to see what it skipped and why`
  }];
}
function dashboardSignals(crawls) {
  if (!crawls) {
    return [];
  }
  let unfinished = 0;
  for (const run of crawls) {
    if (run.state === "failed" || !run.finished && run.state === "running") {
      unfinished += 1;
    }
  }
  if (unfinished === 0) {
    return [];
  }
  return [{
    tool: "dashboard",
    count: unfinished,
    label: `${unfinished} ${unfinished === 1 ? "task" : "tasks"} did not finish — open Dashboard to see which`
  }];
}
function attentionFor(signals, toolId) {
  return signals.find((signal) => signal.tool === toolId);
}

